    # A lone colored bar can act as the length template; otherwise use
    # the median observed bar length.
    per_color = {}
    for key, color, a, b in runs:
        per_color.setdefault(color, []).append(b - a + 1)
    lone = [lens[0] for lens in per_color.values() if len(lens) == 1]
    repeated = [lens for lens in per_color.values() if len(lens) > 1]
    if len(lone) == 1 and repeated:
        target = lone[0]
    else:
        lengths = sorted(b - a + 1 for _, _, a, b in runs)
        target = lengths[len(lengths) // 2]

    out = [[bg] * w for _ in range(h)]
    for key, color, a, b in runs:
        # Keep the high-coordinate endpoint fixed while resizing each bar.
        for t in range(b - target + 1, b + 1):
            if (dr, dc) == (0, 1):
                r, c = key, t
            elif (dr, dc) == (1, 0):
                r, c = t, key
            elif (dr, dc) == (1, 1):
                r, c = t, t - key
            else:
                r, c = t, key - t
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color

    return out
